module top_module(
    input A,
    input B,
    input C,
    input D,
    output reg [15:0] Y
);reg [3:0] stage1_out;
reg [3:0] stage2_out;
reg [3:0] stage3_out;

always @ (posedge A or posedge B or posedge C or posedge D) begin
    stage1_out <= {A, B, C, D};
end

always @ (posedge A or posedge B or posedge C or posedge D) begin
    stage2_out <= stage1_out;
end

always @ (posedge A or posedge B or posedge C or posedge D) begin
    stage3_out <= stage2_out;
end

always @ (posedge A or posedge B or posedge C or posedge D) begin
    case (stage3_out)
        4'b0000: Y <= 16'b0000000000000001;
        4'b0001: Y <= 16'b0000000000000010;
        4'b0010: Y <= 16'b0000000000000100;
        4'b0011: Y <= 16'b0000000000001000;
        4'b0100: Y <= 16'b0000000000010000;
