module top_module(
    input               clk         ,   
    input               rst_n       ,
    input       [7:0]   data_in     ,
    input               valid_a     ,
    input               ready_b     ,

    output              ready_a     ,
    output  reg         valid_b     ,
    output  reg [9:0]   data_out
);reg [7:0] acc_reg;
reg [7:0] booth_reg;
reg [1:0] booth_sel;

assign ready_a = ~valid_b;
assign booth_sel = {booth_reg[7], data_in[7]};
assign data_out = acc_reg;

always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        acc_reg <= 0;
        booth_reg <= 0;
        valid_b <= 0;
    end else begin
        if (valid_a && ready_b) begin
            booth_reg <= {booth_reg[6:0], booth_sel};
            case (booth_sel)
                2'b00: acc_reg <= acc_reg + data_in;
                2'b01: acc_reg <= acc_reg + (data_in >> 1);
                2'b10: acc_reg <= acc_reg + (data_in << 1);
                2'b11: acc_reg <= acc_reg + (~data_in + 1);
            endcase
            if (booth_sel[1]) begin
                valid_b <= 1;
            end
        end
        if (valid_b && ready_a) begin
            valid_b <= 0;
        end
    end
end

endmodule

