module top_module(
    input               clk         ,   
    input               rst_n       ,
    input       [7:0]   data_in     ,
    input               valid_a     ,
    input               ready_b     ,

    output              ready_a     ,
    output  reg         valid_b     ,
    output  reg [9:0]   data_out
);reg [7:0] data_reg [0:3];
reg [1:0] cnt;

wire [7:0] data_in_reg;
assign data_in_reg = (cnt == 0) ? data_in : data_reg[cnt-1];

always @(posedge clk or negedge rst_n) begin
    if(!rst_n) begin
        cnt <= 0;
        valid_b <= 0;
        data_out <= 0;
        // Reset individual elements of data_reg
        data_reg[0] <= 0;
        data_reg[1] <= 0;
        data_reg[2] <= 0;
        data_reg[3] <= 0;
    end
    else begin
        if(valid_a && ready_b) begin
            data_reg[cnt] <= data_in;
            cnt <= cnt + 1;
            if(cnt == 3) begin
                valid_b <= 1;
            end
        end
        if(valid_b && ready_a) begin
            data_out <= {data_reg[3], data_reg[2], data_reg[1], data_reg[0], data_in_reg};
            valid_b <= 0;
            cnt <= 0;
        end
    end
end

assign ready_a = !valid_b;

endmodule

