module top_module(input wire clk,
                input wire reset,
                output empty);parameter M = 35;


localparam N = $clog2(M) + 1;


reg [N-1:0] divcounter = 0;


always @(posedge clk)
    if (reset == 1)
        divcounter <= M;
    else
        if (divcounter > 0)
            divcounter <= divcounter - 1;


assign empty = ~| divcounter;

endmodule

