code:
module fsm_process_control (
        input clk,
        input rst,
        input start,
        input finish,
        output reg out);

    parameter BEGIN = 0, PROCESS = 1, END = 2;
    reg [1:0] state, next_state;

    always @(posedge clk) begin
        if (rst) state <= BEGIN;
        else state <= next_state;
    end

    always_comb begin
        case (state)
            BEGIN: next_state = start ? PROCESS : BEGIN;
            PROCESS: next_state = finish ? END : PROCESS;
            END: next_state = rst ? BEGIN : END;
            default: next_state = 'x;
        endcase
    end

    assign out = (state == PROCESS) || (state == END);

endmodule

