module top_module(
  input ref_clk,
  input fb_clk,
  input reset,
  input delay_ctrl,
  output out_clk
);parameter n = 8; // number of delay stages
parameter delay_step = 10; // delay step size in picoseconds

reg [n-1:0] delay_line; // delay line implemented as a shift register
reg [n-1:0] delay_ctrl_reg; // register to hold the delay control value
reg [n-1:0] error; // register to hold the error signal

wire [n-1:0] fb_clk_delayed; // delayed feedback clock signal
wire [n-1:0] ref_clk_delayed; // delayed reference clock signal

assign fb_clk_delayed = delay_line;
assign ref_clk_delayed = {delay_line[n-2:0], ref_clk};

assign out_clk = ref_clk_delayed[n-1]; // output synchronized clock signal

always @(posedge fb_clk or posedge reset) begin
  if (reset) begin
    delay_line <= 0;
    delay_ctrl_reg <= 0;
    error <= 0;
  end else begin
    delay_line <= {delay_line[n-2:0], fb_clk_delayed[n-1]};
    error <= ref_clk_delayed ^ fb_clk_delayed;
    delay_ctrl_reg <= delay_ctrl_reg + delay_ctrl - error;
    delay_line <= {delay_line[n-2:0], delay_ctrl_reg[n-1]};
  end
end

endmodule

