description:
Design a clock generation module for a Serial Peripheral Interface (SPI) that produces a controllable output clock signal (`clk_out`) based on an input clock (`clk_in`), a reset signal (`rst`), and a divider value. The module includes a counter that counts down to facilitate the generation of a clock with a frequency that can be divided down by the specified `divider`. The output clock toggles based on the counter reaching zero, and additional functionality generates positive and negative edge signals (`pos_edge` and `neg_edge`) to indicate when the clock transitions occur. The module also supports enabling and disabling the clock output and handling special conditions, enhancing its versatility in various SPI communication scenarios.
module top_module(
  input clk_in, rst, go, enable, last_clk,
  input [31:0] divider,
  output reg clk_out, pos_edge, neg_edge
);

code:
module top_module(
  input clk_in, rst, go, enable, last_clk,
  input [31:0] divider,
  output reg clk_out, pos_edge, neg_edge
);reg [31:0] cnt; // clock counter

  wire cnt_zero = (cnt == {32{1'b0}}); // counter is equal to zero
  wire cnt_one = (cnt == {{31{1'b0}}, 1'b1}); // counter is equal to one

  // Counter counts half period
  always @(posedge clk_in or posedge rst) begin
    if (rst) begin
      cnt <= 32'h80000000;
    end else begin
      if (!enable || cnt_zero) begin
        cnt <= divider;
      end else begin
        cnt <= cnt - 1'b1;
      end
    end
  end

  // clk_out is asserted every other half period
  always @(posedge clk_in or posedge rst) begin
    if (rst) begin
      clk_out <= 1'b0;
    end else begin
      clk_out <= (enable && cnt_zero && (!last_clk || clk_out)) ? ~clk_out : clk_out;
    end
  end

  // Pos and neg edge signals
  always @(posedge clk_in or posedge rst) begin
    if (rst) begin
      pos_edge <= 1'b0;
      neg_edge <= 1'b0;
    end else begin
      pos_edge <= (enable && !clk_out && cnt_one) || (divider == 0 && clk_out) || (divider == 0 && go && !enable);
      neg_edge <= (enable && clk_out && cnt_one) || (divider == 0 && !clk_out && enable);
    end
  end

endmodule

