description:
Design a switch debouncing circuit. The module synchronizes the state of a switch input with a clock signal to eliminate false triggering due to mechanical bounce. It uses a counter to track the duration for which the switch is stable, and toggles the output switch state only when the switch has remained in the same state for a predefined count, ensuring a clean and stable output.
module top_module(
    input clk, 
    input sw,  
    output reg sw_state  
    );

code:
module top_module(
    input clk, 
    input sw,  
    output reg sw_state  
    );reg sw_sync_0;
always @(posedge clk) sw_sync_0 <= sw; 
reg sw_sync_1;
always @(posedge clk) sw_sync_1 <= sw_sync_0;


reg [15:0] sw_cnt;
always @(posedge clk)
if(sw_state==sw_sync_1)
    sw_cnt <= 0;
else
begin
    sw_cnt <= sw_cnt + 1'b1;  
    if(sw_cnt == 16'hffff) sw_state <= ~sw_state;  
end
endmodule

