module mealy_machine (
  input in,
  input [1:0] state,
  output reg [1:0] next_state,
  output reg out);parameter D=0, E=1, F=2, G=3;

    always_comb begin
        case (state)
            D: begin
                next_state = in ? E : G;
                out = in ? 0 : 1;
            end
            E: begin
                next_state = in ? F : D;
                out = in ? 1 : 0;
            end
            F: begin
                next_state = in ? G : E;
                out = in ? 1 : 0;
            end
            G: begin
                next_state = in ? D : F;
                out = in ? 0 : 1;
            end
        endcase
    end

endmodule

