description:
Design a parallel-in serial-out (PISO) shift register capable of loading data from two parallel 8-bit inputs (par_in_a and par_in_b) into a shift register on the rising edge of the clock. The module allows for shifting the data out serially through the output (ser_out), with the most significant bit shifting out first. The shift operation occurs only when the shift control signal is active, and the register can be reset asynchronously using the reset_n signal. The design effectively manages input loading and shifting operations based on control signals, making it suitable for transferring parallel data to a serial format.
module top_module(
    input clk, reset_n, load_a, load_b, shift,
    input [7:0] par_in_a, par_in_b,
    output reg ser_out
);

code:
module top_module(
    input clk, reset_n, load_a, load_b, shift,
    input [7:0] par_in_a, par_in_b,
    output reg ser_out
);reg [7:0] shift_reg;

always @(posedge clk or negedge reset_n) begin
    if (!reset_n) begin
        shift_reg <= 8'b0;
        ser_out <= 1'b0;
    end
    else begin
        if (load_a) begin
            shift_reg <= par_in_a;
        end
        else if (load_b) begin
            shift_reg <= par_in_b;
        end
        else if (shift) begin
            shift_reg <= {shift_reg[6:0], shift_reg[7]};
            ser_out <= shift_reg[0];
        end
    end
end

endmodule

