module gray_code_counter (
	input clk,
	input resetn,
	output reg [3:0] q);

always @(posedge clk or negedge resetn) begin
	if (~resetn)
		q <= 4'b0000;
	else
		q <= q ^ {1'b0, q[3:1]};
end

endmodule

module top_module(A, B, Cin, S, Cout);input [3:0] A, B;
input Cin;
output [3:0] S;
output Cout;

wire [3:0] X;
wire [3:0] Y;

assign X = A ^ B;
assign Y = X ^ Cin;
assign S = Y;
assign Cout = (A & B) | (X & Cin);

endmodule

module top_module(A, B, Ci, S, Co);input A, B, Ci;
  output S, Co;

  wire n1, n2, n3;

  assign n1 = A ^ B;          // XOR A and B
  assign S = n1 ^ Ci;        // XOR n1 and Ci to get S

  assign n2 = A & B;         // AND A and B
  assign n3 = n1 & Ci;       // AND n1 and Ci
  assign Co = n2 | n3;       // OR n2 and n3 to get Co

endmodule

module top_module(
        output reg dout,
        input din,
        input rst,
        input clk);reg [2:0]m;
  reg [3:0]count;


  always@(posedge din or negedge rst)
    begin
      if(!rst)
        begin
          m <= 0;
        end
      else
        begin
          m <= m + 1;
        end
    end



  always@(posedge clk or negedge rst)
    begin
      if(!rst)
        begin
          count <= 0;
          dout <= 0;
        end
      else if(count == 4'b1111)  
        begin
          if(m > 3'b001)  
            dout <= 1;
          else            
            dout <= 0;
          m <= 0;
          count <= 0;
        end
      else
        begin
          count <= count + 1;
        end
    end

endmodule

