module reg_file_16x16_tb;

    // Testbench signals (sequential circuit)
    reg clk;
    reg [3:0] r_addr0;
    reg [3:0] r_addr1;
    reg [3:0] r_addr2;
    reg [3:0] r_addr3;
    reg [3:0] w_addr;
    reg [15:0] w_data;
    reg we;
    wire [15:0] r_data0;
    wire [15:0] r_data1;
    wire [15:0] r_data2;
    wire [15:0] r_data3;

    // Test tracking
    integer test_num;
    integer pass_count;
    integer fail_count;

    // Instantiate the DUT (Device Under Test)
    reg_file_16x16 dut (
        .clk(clk),
        .r_addr0(r_addr0),
        .r_addr1(r_addr1),
        .r_addr2(r_addr2),
        .r_addr3(r_addr3),
        .w_addr(w_addr),
        .w_data(w_data),
        .we(we),
        .r_data0(r_data0),
        .r_data1(r_data1),
        .r_data2(r_data2),
        .r_data3(r_data3)
    );

    // Clock generation (10ns period)
    initial begin
        clk = 0;
        forever #5 clk = ~clk;
    end

        task reset_dut;

        integer i;
        begin
            we = 0;
            w_addr = 0;
            w_data = 0;
            r_addr0 = 0;
            r_addr1 = 0;
            r_addr2 = 0;
            r_addr3 = 0;


            @(posedge clk);


            for (i = 0; i < 16; i = i + 1) begin
                @(negedge clk);
                we = 1;
                w_addr = i;
                w_data = 16'h0000;
                @(posedge clk);
                we = 0;
            end
            #5;
            $display("Reset Complete: All registers cleared.");
        end
        endtask
    task testcase001;

        begin
            reset_dut();
            test_num = 1;
            $display("\nTestcase %0d: Basic Write and Read", test_num);

            @(negedge clk);
            we = 1;
            w_addr = 4'h5;
            w_data = 16'hABCD;

            @(posedge clk);
            #2 we = 0;

            r_addr0 = 4'h5;
            #5;
            #1;

            check_outputs(16'hABCD, 16'h0000, 16'h0000, 16'h0000);
        end
        endtask

    task testcase002;

        begin
            reset_dut();
            test_num = 2;
            $display("\nTestcase %0d: Multi-port Read", test_num);


            @(negedge clk); we = 1; w_addr = 4'h1; w_data = 16'h1111; @(posedge clk);
            @(negedge clk); we = 1; w_addr = 4'h2; w_data = 16'h2222; @(posedge clk);
            @(negedge clk); we = 1; w_addr = 4'h3; w_data = 16'h3333; @(posedge clk);
            @(negedge clk); we = 1; w_addr = 4'h4; w_data = 16'h4444; @(posedge clk);

            #2 we = 0;
            r_addr0 = 4'h1;
            r_addr1 = 4'h2;
            r_addr2 = 4'h3;
            r_addr3 = 4'h4;

            #5;
            #1;

            check_outputs(16'h1111, 16'h2222, 16'h3333, 16'h4444);
        end
        endtask

    task testcase003;

        begin
            reset_dut();
            test_num = 3;
            $display("\nTestcase %0d: Write Enable Check", test_num);


            @(negedge clk); we = 1; w_addr = 4'hA; w_data = 16'hAAAA; @(posedge clk);


            @(negedge clk); we = 0; w_addr = 4'hA; w_data = 16'hFFFF; @(posedge clk);

            #2;
            r_addr0 = 4'hA;
            #5;

            #1;


            check_outputs(16'hAAAA, 16'h0000, 16'h0000, 16'h0000);
        end
        endtask

    task testcase004;

        begin
            reset_dut();
            test_num = 4;
            $display("\nTestcase %0d: Simultaneous read of same address", test_num);

            @(negedge clk); we = 1; w_addr = 4'hF; w_data = 16'h55AA; @(posedge clk);

            #2 we = 0;
            r_addr0 = 4'hF;
            r_addr1 = 4'hF;
            r_addr2 = 4'hF;
            r_addr3 = 4'hF;

            #5;
            #1;

            check_outputs(16'h55AA, 16'h55AA, 16'h55AA, 16'h55AA);
        end
        endtask

    task testcase005;

        begin
            reset_dut();
            test_num = 5;
            $display("\nTestcase %0d: Overwriting data", test_num);

            @(negedge clk); we = 1; w_addr = 4'h7; w_data = 16'h1234; @(posedge clk);
            @(negedge clk); we = 1; w_addr = 4'h7; w_data = 16'h5678; @(posedge clk);

            #2 we = 0;
            r_addr0 = 4'h7;
            #5;
            #1;

            check_outputs(16'h5678, 16'h0000, 16'h0000, 16'h0000);
        end
        endtask

    task testcase006;

        begin
            reset_dut();
            test_num = 6;
            $display("\nTestcase %0d: Boundary Address Check (0 and 15)", test_num);

            @(negedge clk); we = 1; w_addr = 4'h0; w_data = 16'h0001; @(posedge clk);
            @(negedge clk); we = 1; w_addr = 4'hF; w_data = 16'hF00F; @(posedge clk);

            #2 we = 0;
            r_addr0 = 4'h0;
            r_addr1 = 4'hF;
            r_addr2 = 4'h0;
            r_addr3 = 4'hF;

            #5;
            #1;

            check_outputs(16'h0001, 16'hF00F, 16'h0001, 16'hF00F);
        end
        endtask

    // Test stimulus
    initial begin
        // Initialize
        test_num = 0;
        pass_count = 0;
        fail_count = 0;

        $display("========================================");
        $display("reg_file_16x16 Testbench");
