module top_module(
    datain,    // required port, DDR input data
    inclock,   // required port, input reference clock to sample data by
    inclocken, // enable data clock
    aset,      // asynchronous set
    aclr,      // asynchronous clear
    sset,      // synchronous set
    sclr,      // synchronous clear
    dataout_h, // data sampled at the rising edge of inclock
    dataout_l  // data sampled at the falling edge of inclock
);parameter width = 1;
parameter power_up_high = "OFF";
parameter invert_input_clocks = "OFF";
parameter intended_device_family = "Stratix";
parameter lpm_type = "altddio_in";
parameter lpm_hint = "UNUSED";

input [width-1:0] datain;
input inclock;
input inclocken;
input aset;
input aclr;
input sset;
input sclr;

output reg [width-1:0] dataout_h;
output reg [width-1:0] dataout_l;

reg [width-1:0] data_reg;

always @(posedge inclock or negedge inclock) begin
    if (inclocken) begin
        data_reg <= datain;
        dataout_h <= data_reg;
        dataout_l <= data_reg;
    end
end

always @(posedge inclock) begin
    if (sset) begin
        data_reg <= 1'b1;
    end else if (sclr) begin
        data_reg <= 1'b0;
    end
end

always @(data_reg or aset or aclr) begin
    if (aclr) begin
        data_reg <= 1'b0;
    end else if (aset) begin
        data_reg <= 1'b1;
    end
end

initial begin
    if (power_up_high == "ON") begin
        data_reg <= 1'b1;
    end else begin
        data_reg <= 1'b0;
    end
end

endmodule

