module ring_counter(
    input wire clk,
    input wire rst_n,
    output reg [5:0] ring_out
    );

always @(posedge clk or negedge rst_n) begin
    if (!rst_n)
        ring_out <= 6'b100000;
    else
        ring_out <= {ring_out[4:0], ring_out[5]};
end

endmodule
